local WHITE = Color3.fromRGB(255, 255, 255)
local BLACK = Color3.fromRGB(0, 0, 0)
local TEXT = Color3.fromRGB(215, 215, 215)
local hex = {}
for i = 0, 15 do
    hex[string.format("%X", i)] = i
end
local lastFrame = 0
local currentRows = {}
local started = os.clock()
local paused = false
local pauseStarted = 0
local pausedTime = 0
local previous = {}

local function loadFrame(index)
    if index == lastFrame then return end
    local data = DATA[index]
    if not data then return end
    lastFrame = index
    local pos = 1
    currentRows = {}
    for y = 1, HEIGHT do
        local spans = {}
        local openX = nil
        for x = 1, WIDTH do
            local nibbleIndex = math.floor((x - 1) / 4)
            local ch = string.sub(data, pos + nibbleIndex, pos + nibbleIndex)
            local n = hex[ch] or 0
            local mask = 2 ^ (3 - ((x - 1) % 4))
            local on = math.floor(n / mask) % 2 == 1
            if on and not openX then
                openX = x
            elseif not on and openX then
                spans[#spans + 1] = {openX, x - openX}
                openX = nil
            end
        end
        if openX then
            spans[#spans + 1] = {openX, WIDTH - openX + 1}
        end
        currentRows[y] = spans
        pos = pos + WIDTH / 4
    end
end

local function update()
    local held = {}
    for _, key in getpressedkeys() do
        held[tostring(key):upper()] = true
    end
    if held["P"] and not previous["P"] then
        paused = not paused
        if paused then
            pauseStarted = os.clock()
        else
            pausedTime = pausedTime + os.clock() - pauseStarted
        end
    end
    if held["R"] and not previous["R"] then
        started = os.clock()
        pausedTime = 0
        if paused then pauseStarted = started end
        lastFrame = 0
    end
    previous = held
end

local function render()
    local now = paused and pauseStarted or os.clock()
    local elapsed = math.max(0, now - started - pausedTime)
    local frame = (math.floor(elapsed * FPS) % FRAME_COUNT) + 1
    loadFrame(frame)

    local vp = Camera.ViewportSize
    local scale = math.min((vp.X - 40) / WIDTH, (vp.Y - 85) / HEIGHT)
    local w, h = WIDTH * scale, HEIGHT * scale
    local ox, oy = (vp.X - w) / 2, (vp.Y - h) / 2
    DrawingImmediate.FilledRectangle(Vector2.new(ox, oy), Vector2.new(w, h), BLACK, 1, 0)

    for y = 1, HEIGHT do
        local spans = currentRows[y]
        if spans then
            for _, span in spans do
                DrawingImmediate.FilledRectangle(
                    Vector2.new(ox + (span[1] - 1) * scale, oy + (y - 1) * scale),
                    Vector2.new(span[2] * scale + 0.15, scale + 0.15),
                    WHITE, 1, 0
                )
            end
        end
    end

    DrawingImmediate.OutlinedText(
        Vector2.new(vp.X / 2, oy - 22), 19, TEXT, 1,
        "BAD APPLE!!  |  P pause  R restart", true
    )
end

RunService.PreLocal:Connect(update)
RunService.Render:Connect(render)
print("Bad Apple player loaded - " .. FRAME_COUNT .. " frames at " .. FPS .. " FPS")
